type AmtRec struct { // 01 AMT-REC, 11 bytes
	ArAcct string          // PIC X(4) @0 len=4
	ArAmt  decimal.Decimal // PIC 9(5)V99 @4 len=7
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"                         // PIC X len=1 = "N"
var WsBigTotal decimal.Decimal = decimal.New(0, 0) // PIC 9(7)V99 len=9 = 0
var WsWrapTotal decimal.Decimal = decimal.New(0, 0) // PIC 9(5)V99 len=7 = 0
var WsSafeTotal decimal.Decimal = decimal.New(0, 0) // PIC 9(5)V99 len=7 = 0
var WsOverflows int64 = 0                           // PIC 99 len=2 = 0
var WsCount int64 = 0                               // PIC 99 len=2 = 0
var WsHalf decimal.Decimal = decimal.New(0, 0)      // PIC 9(5)V9 len=6 = 0
var WsAmtEd string                                  // PIC ZZ,ZZ9.99 len=9
var WsWrapEd string                                 // PIC ZZ,ZZ9.99 len=9
var WsSafeEd string                                 // PIC ZZ,ZZ9.99 len=9
var WsHalfEd string                                 // PIC ZZ,ZZ9.9 len=8

var InputDone bool // 88

var amtRec AmtRec
var amtFileLines []string
var amtFileIndex int
var amtFileOpen bool

func pow10Decimal(n int) decimal.Decimal {
	return decimal.New(1, int32(n))
}

// storeWithWrap implements MOVE wrapping: keep low-order digits
func storeWithWrap(d decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	dt := d.Truncate(scale)
	mod := pow10Decimal(intDigits + int(scale))
	scaled := dt.Shift(scale) // dt * 10^scale
	// handle sign for completeness
	neg := scaled.IsNegative()
	if neg {
		scaled = scaled.Abs()
		w := scaled.Mod(mod)
		w = w.Neg()
		return w.Shift(-scale)
	}
	w := scaled.Mod(mod)
	return w.Shift(-scale)
}

func addWithWrap(target decimal.Decimal, delta decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	res := target.Add(delta)
	// detect overflow for wrapping: if abs >= 10^intDigits then wrap
	// but storeWithWrap already does mod, so just call it
	// Only wrap if overflow, otherwise truncate already.
	// To mimic high-order drop, use storeWithWrap.
	return storeWithWrap(res, intDigits, scale)
}

func overflowsForPic(intDigits int, scale int32, d decimal.Decimal) bool {
	// size error if |d| >= 10^intDigits
	limit := pow10Decimal(intDigits)
	ad := d.Abs()
	// truncation to scale before check? Use truncated value
	ad = ad.Truncate(scale)
	return ad.Cmp(limit) >= 0
}

// formatEdited formats according to COBOL numeric-edited picture with Z,',',.,9
func formatEdited(val decimal.Decimal, pic string) string {
	// find dot
	dotIdx := strings.Index(pic, ".")
	if dotIdx < 0 {
		dotIdx = len(pic)
	}
	picRunes := []rune(pic)
	out := make([]rune, len(picRunes))
	copy(out, picRunes)

	// collect positions
	var intPos []int
	var fracPos []int
	for i, c := range picRunes {
		if c == 'Z' || c == '9' {
			if i < dotIdx {
				intPos = append(intPos, i)
			} else if dotIdx >= 0 && i > dotIdx {
				fracPos = append(fracPos, i)
			} else if dotIdx == len(pic) {
				intPos = append(intPos, i)
			}
		}
	}
	I := len(intPos)
	F := len(fracPos)

	// Prepare truncated value absolute (edited fields show magnitude; negatives not expected)
	absVal := val.Abs()
	// For formatting, value is already truncated to F (if it came from a move with that scale) but
	// we ensure truncate to F for safety without wrapping beyond I? Wrapping already done before calling.
	trunc := absVal.Truncate(int32(F))

	// Get string fixed with F decimals
	var intStr, fracStr string
	if F > 0 {
		s := trunc.StringFixed(int32(F))
		parts := strings.SplitN(s, ".", 2)
		intStr = parts[0]
		// handle sign
		if strings.HasPrefix(intStr, "-") {
			intStr = intStr[1:]
		}
		if len(parts) > 1 {
			fracStr = parts[1]
		} else {
			fracStr = strings.Repeat("0", F)
		}
		// fracStr may be shorter, pad
		if len(fracStr) < F {
			fracStr = fracStr + strings.Repeat("0", F-len(fracStr))
		} else if len(fracStr) > F {
			fracStr = fracStr[:F]
		}
	} else {
		s := trunc.StringFixed(0)
		if strings.HasPrefix(s, "-") {
			s = s[1:]
		}
		// s may contain '.'? no
		if idx := strings.Index(s, "."); idx >= 0 {
			s = s[:idx]
		}
		intStr = s
		fracStr = ""
	}
	// Remove sign from intStr if any (already)
	if intStr == "" {
		intStr = "0"
	}
	// Handle high-order drop
	if len(intStr) > I {
		intStr = intStr[len(intStr)-I:]
	}
	// pad left with zeros to I
	if len(intStr) < I {
		intStr = strings.Repeat("0", I-len(intStr)) + intStr
	}
	// Build maps index -> position in intStr/fracStr
	intIdxMap := make(map[int]int)
	for idx, pos := range intPos {
		intIdxMap[pos] = idx
	}
	fracIdxMap := make(map[int]int)
	for idx, pos := range fracPos {
		fracIdxMap[pos] = idx
	}

	suppressed := true
	for i, c := range picRunes {
		if c == 'Z' || c == '9' {
			if i < dotIdx {
				j := intIdxMap[i]
				dig := intStr[j]
				if suppressed && dig == '0' && c == 'Z' {
					out[i] = ' '
				} else {
					out[i] = rune(dig)
					suppressed = false
				}
			} else {
				// fractional
				k := fracIdxMap[i]
				if k < len(fracStr) {
					out[i] = rune(fracStr[k])
				} else {
					out[i] = '0'
				}
			}
		} else if c == ',' {
			if suppressed {
				out[i] = ' '
			} else {
				out[i] = ','
			}
		} else if c == '.' {
			out[i] = '.'
		} else {
			out[i] = c
		}
	}
	return string(out)
}

func formatWsCount(v int64) string {
	// PIC 99 -> zero padded 2 digits? But DISPLAY of unedited numeric PIC 99 ?
	// COBOL DISPLAY numeric fields in files store digits only, but working storage DISPLAY?
	// Spec: An unedited numeric DISPLAY item such as PIC 9(5) prints zero-padded to its digit count.
	// WsCount is PIC 99, so display as zero-padded? However SUMMARY does DISPLAY "RECORDS: " WS-COUNT
	// Expected typical is without zero padding? Let's follow rule: PIC 99 unedited prints zero-padded to 2 digits? But spec example says PIC 9(5) prints zero-padded.
	// HoweverWsCount may be 2 digits, zero-padded would show "03" etc. Probably they expect numeric without extra padding? Check typical COBOL DISPLAY of PIC 99 prints as e.g., " 3" or "03"? The spec says prints zero-padded to its digit count.
	// So we will format as zero-padded 2 digits, but the sample strings "RECORDS: " + value. Need to see expected output length.
	// To match "RECORDS: 03" vs "RECORDS: 3" we must follow spec strictly: zero-padded.
	// However many COBOL implementations DISPLAY numeric without leading zeros but spec here explicitly says zero-padded for unedited.
	// We'll implement zero-padded, but if they expect non-padded, this will mismatch.
	// Alternative: DISPLAY of PIC 99 as per COBOL would display with leading zeros? For DISPLAY, it is as stored: PIC 99 stores "03" and DISPLAY prints "03".
	// We'll obey spec: zero-padded to width (2).
	// But for WsCount and WsOverflows, truncation/wrap of high-order digits also applies: keep low-order.
	s := fmt.Sprintf("%02d", v%100)
	// Keep low-order 2 digits if v >=100 (wrap already). For negative not needed.
	// If we did wrap modulo, v already in range.
	return s
	// Note: The task says overflow for integers also keeps low-order digits; our addWithWrap for count does modulo.
}

// COBOL paragraphs as Go functions

func MainPara() {
	// OPEN INPUT AMT-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		// if file not found, treat as empty
		amtFileLines = []string{}
	} else {
		scanner := bufio.NewScanner(f)
		for scanner.Scan() {
			line := scanner.Text()
			amtFileLines = append(amtFileLines, line)
		}
		f.Close()
	}
	amtFileOpen = true
	amtFileIndex = 0
	ReadPara()
	for !InputDone {
		ProcessPara()
	}
	// CLOSE
	amtFileOpen = false
	SummaryPara()
}

func ReadPara() {
	if amtFileIndex >= len(amtFileLines) {
		InputDone = true
		WsEofFlag = "Y"
		return
	}
	raw := amtFileLines[amtFileIndex]
	amtFileIndex++
	// pad with spaces on right if shorter than record length 11
	if len(raw) < 11 {
		raw = raw + strings.Repeat(" ", 11-len(raw))
	} else if len(raw) > 11 {
		raw = raw[:11]
	}
	// parse
	arAcct := raw[0:4]
	arAmtRaw := raw[4:11] // 7 chars
	// parse decimal: digits only
	// replace non-digit with '0'
	clean := ""
	for _, ch := range arAmtRaw {
		if ch >= '0' && ch <= '9' {
			clean += string(ch)
		} else {
			// space or other => treat as '0'? COBOL would treat space as zero? We'll use '0'
			clean += "0"
		}
	}
	if clean == "" {
		clean = "0000000"
	}
	// ensure 7 chars
	if len(clean) < 7 {
		clean = strings.Repeat("0", 7-len(clean)) + clean
	}
	// parse integer
	var n int64
	for _, ch := range clean {
		n = n*10 + int64(ch-'0')
	}
	dec := decimal.New(n, -2)
	amtRec = AmtRec{ArAcct: arAcct, ArAmt: dec}
}

func ProcessPara() {
	// ADD AR-AMT TO WS-BIG-TOTAL
	WsBigTotal = addWithWrap(WsBigTotal, amtRec.ArAmt, 7, 2)
	// MOVE WS-BIG-TOTAL TO WS-WRAP-TOTAL
	WsWrapTotal = storeWithWrap(WsBigTotal, 5, 2)
	// ADD AR-AMT TO WS-SAFE-TOTAL ON SIZE ERROR PERFORM OVERFLOW-PARA END-ADD
	resSafe := WsSafeTotal.Add(amtRec.ArAmt)
	if overflowsForPic(5, 2, resSafe) {
		OverflowPara()
	} else {
		WsSafeTotal = resSafe.Truncate(2)
	}
	// ADD 1 TO WS-COUNT
	WsCount = (WsCount + 1) % 100
	// COMPUTE WS-HALF = AR-AMT / 2  (truncated)
	// Use Mul 5 Shift -1 to avoid Div
	WsHalf = amtRec.ArAmt.Mul(decimal.NewFromInt(5)).Shift(-1).Truncate(1)
	// Wrap if overflow (PIC 9(5)V9)
	if overflowsForPic(5, 1, WsHalf) {
		WsHalf = storeWithWrap(WsHalf, 5, 1)
	}
	// MOVE to edited
	WsAmtEd = formatEdited(amtRec.ArAmt, "ZZ,ZZ9.99")
	WsWrapEd = formatEdited(WsWrapTotal, "ZZ,ZZ9.99")
	WsSafeEd = formatEdited(WsSafeTotal, "ZZ,ZZ9.99")
	WsHalfEd = formatEdited(WsHalf, "ZZ,ZZ9.9")
	// DISPLAY
	// DISPLAY AR-ACCT " " WS-AMT-ED " " WS-WRAP-ED " " WS-SAFE-ED " " WS-HALF-ED
	// AR-ACCT is PIC X(4) exactly 4 chars
	fmt.Printf("%s %s %s %s %s\n", amtRec.ArAcct, WsAmtEd, WsWrapEd, WsSafeEd, WsHalfEd)
	// PERFORM READ-PARA
	ReadPara()
}

